mapper.insert:
INSERT INTO record_comment_reaction (
  workspace_id, comment_id, user_id, reaction
)
SELECT #{workspaceId}, c.id, #{userId}, #{reaction}
FROM record_comment c
WHERE c.workspace_id = #{workspaceId}
  AND c.id = #{commentId}
  AND c.deleted_at IS NULL

mapper.delete:
DELETE FROM record_comment_reaction
WHERE workspace_id = #{workspaceId}
  AND comment_id = #{commentId}
  AND user_id = #{userId}
  AND reaction = #{reaction}

mapper.select:
SELECT target_id, COUNT(*) AS open_threads
FROM record_comment_thread
WHERE workspace_id = #{workspaceId}
  AND target_type = #{targetType}
  AND state = 'open'
  AND target_id IN
  #{targetId}
GROUP BY target_id
ORDER BY target_id

