DELETE FROM record_comment_thread
WHERE workspace_id = #{workspaceId} AND id = #{id}
  AND NOT EXISTS (
    SELECT 1
    FROM record_comment
    WHERE workspace_id = #{workspaceId} AND thread_id = #{id}
  )

